ruleContent.content:
#contentb@html||#zcontent@html||#ccontent@html||#ycontent@html||#contentc@html||#acontent@html||#content@html||#YiJianZhan@html||#contenta@html@js:
(() => {
    const currentIndex = chapter.index;
    const baseIndex = book.durChapterIndex;
    const indexDiff = currentIndex - baseIndex; 

    if (Math.abs(indexDiff) > 2) {
        return ''; 
    }

    const delay = Math.random() * 1400 + 100;
    Packages.java.lang.Thread.sleep(delay);

    return java.getString('[id*="content"]@html', result);
})()

ruleExplore.coverUrl:
.db@href
@js:
var href = result;
var id = href.split('/').pop().replace('.html','');
var len = id.length;
var prefix = len <= 3 ? '0' : id.slice(0, len-3);
'https://www.8xbook.org/files/article/image/'+prefix+'/'+id+'/'+id+'s.jpg';

ruleToc.nextTocUrl:
#pagestats@textNodes
@js:
    var nodes = result;
    var totalPage = 0;

    for (
    	var i = 0; i < nodes.length; i++) {
        if (nodes[i].trim().startsWith('/')) {
            totalPage = parseInt(nodes[i].trim().substring(1));
            break;
        }
    }

    var data = [];
    if (totalPage > 1) {
    var basePart = baseUrl.replace(/_1\.html$/, '_');
        for (
        	var i = 2; i <= totalPage; i++) {
            data.push(basePart + i + '.html');
        }
    }
    data;

